import sys

def abbreviate(word: str) -> str:
    if len(word) > 10:
        return f"{word[0]}{len(word) - 2}{word[-1]}"
    return word

def main():
    lines = sys.stdin.read().splitlines()
    if not lines:
        return
    for word in lines[1:]:
        if word.strip():
            print(abbreviate(word.strip()))

