package main

import (
    "fmt"
)

func main() {
    var n, k int
    if _, err := fmt.Scan(&n, &k); err != nil {
        return
    }

    scores := make([]int, n)
    for i := 0; i < n; i++ {
        fmt.Scan(&scores[i])
    }

    cutoff := scores[k-1]
    advancing := 0

    for _, s := range scores {
        if s >= cutoff && s > 0 {
            advancing++
        }
    }

    fmt.Println(advancing)
}

