class Solution:
    def compare_strings(self, s1: str, s2: str) -> int:
        s1_lower = s1.lower()
        s2_lower = s2.lower()

        if s1_lower < s2_lower:
            return -1
        elif s1_lower > s2_lower:
            return 1
        return 0

use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let input = input.trim();

    let mut digits: Vec<char> = input.chars().filter(|c| c.is_digit(10)).collect();
    digits.sort_unstable();

    let result: Vec<String> = digits.into_iter().map(|d| d.to_string()).collect();
    println!("{}", result.join("+"));
}

export function capitalizeWord(word: string): string {
  if (!word) return "";
  return word.charAt(0).toUpperCase() + word.slice(1);
}
